#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const sharedPath = path.join(root, 'references/SHARED_CONTEXT.json');
const shared = JSON.parse(fs.readFileSync(sharedPath, 'utf8'));
const today = shared.lastUpdated || new Date().toISOString().slice(0, 10);

const content = `# Agent Status Report

**Last Updated**: ${today}
**Generated by**: \`npm run agents:status\`

## Codex (GPT Models)

- **Current Task**: ${shared.coordination?.codexCurrentTask || 'No active Codex task recorded.'}
- **Last Completed**: ${shared.coordination?.codexLastCompleted || 'Sales/client-ops workbench simplification with local contact continuity memory.'}
- **Next Priority**: ${shared.coordination?.codexNextPriority || 'Update .codex files, Codex workflow files when needed, and master files after approved changes.'}
- **Blockers**: ${shared.coordination?.codexBlockers || 'Git metadata is not present in this workspace, so git status/diff cannot be used here.'}
- **Plan File**: \`plans/codex-current-plan.md\`

## Claude Code

- **Current Task**: ${shared.coordination?.claudeCurrentTask || 'No active task recorded in this workspace.'}
- **Last Completed**: ${shared.coordination?.claudeLastCompleted || 'Claude Code peer configuration and shared planning alignment.'}
- **Next Priority**: ${shared.coordination?.claudeNextPriority || 'Read master coordination files before app changes and avoid routine edits to .claude/*.'}
- **Blockers**: ${shared.coordination?.claudeBlockers || 'None recorded.'}
- **Plan File**: \`plans/claude-code-current-plan.md\`

## Sync Status

- Plans aligned through \`.codex/\` and master files.
- No conflicting active tasks recorded.
- Routine app changes do not require \`.claude/*\` edits unless Claude runtime instructions changed.
`;

fs.writeFileSync(path.join(root, 'AGENT_STATUS.md'), content);
console.log('AGENT_STATUS.md generated');
